	function oklchToRgbIfInGamut (L, C, H, out) {
		const hr = H * Math.PI / 180;
		const a = C * Math.cos(hr);
		const b = C * Math.sin(hr);
		const l0 = L + KA0 * a + KB0 * b;
		const m0 = L + KA1 * a + KB1 * b;
		const s0 = L + KA2 * a + KB2 * b;
